        # Parse pre-release identifiers
        if prerelease_part:
            prerelease = prerelease_part.split('.')
        else:
            prerelease = None

        return (major, minor, patch, prerelease)

    def compare_prerelease(pre1, pre2):
        # None means no pre-release (higher precedence)
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # no pre-release > pre-release
        if pre2 is None:
            return -1  # pre-release < no pre-release

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric: compare numerically
                cmp = int(id1) - int(id2)
                if cmp != 0:
                    return cmp
            elif is_num1:
                # Numeric < non-numeric
                return -1
            elif is_num2:
                # Non-numeric > numeric
                return 1
            else:
                # Both non-numeric: compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        return len(pre1) - len(pre2)

