    def sort_key(item):
        parsed_v, original_index, _ = item
        major, minor, patch, prerelease = parsed_v
        # For stable sort with build metadata ignored, use original index as tiebreaker
        return (major, minor, patch, prerelease is not None, prerelease or [], original_index)

    # Custom comparison using the rule that version with pre-release < version without pre-release
    from functools import cmp_to_key

    def compare(item1, item2):
        parsed1, idx1, _ = item1
        parsed2, idx2, _ = item2

        major1, minor1, patch1, pre1 = parsed1
        major2, minor2, patch2, pre2 = parsed2

        if major1 != major2:
