            return minor1 - minor2
        if patch1 != patch2:
            return patch1 - patch2

        cmp = compare_prerelease(pre1, pre2)
        if cmp != 0:
            return cmp

        # Equal precedence: maintain input order
        return idx1 - idx2

    sorted_versions = sorted(parsed, key=cmp_to_key(compare))
    return [v for _, _, v in sorted_versions]

